package com.ninho.shared;
import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @ConditionalOnProperty(name="ninho.game-kind") public class GameService {
 private final JdbcTemplate db;private final GameRules rules;private final String kind;
 public GameService(JdbcTemplate db,GameRules rules,@Value("${ninho.game-kind}")String kind){this.db=db;this.rules=rules;this.kind=kind;}
 private final RowMapper<GameState> mapper=(r,n)->{var g=new GameState();g.id=r.getObject("id",UUID.class);g.userId=r.getObject("user_id",UUID.class);g.definitionId=r.getString("definition_id");g.state=r.getString("state");g.progress=r.getInt("progress");g.version=r.getInt("version");g.readyAt=r.getLong("ready_at");g.resultId=r.getString("result_id");g.createdAt=r.getLong("created_at");String selected=r.getString("selected");g.selected=new ArrayList<>(selected.isEmpty()?List.of():List.of(selected.split(",")));return g;};
 public Map<String,Object> availability(){db.queryForObject("SELECT COUNT(*) FROM game_definition",Integer.class);return Map.of("available",true,"service",kind);}
 public List<Map<String,Object>> catalog(){return db.query("SELECT id,title,description,items FROM game_definition ORDER BY id",(r,n)->Map.of("id",r.getString("id"),"name",r.getString("title"),"detail",r.getString("description"),"items",List.of(r.getString("items").split(","))));}
 private GameState load(UUID id,UUID user,boolean lock){var rows=db.query("SELECT * FROM game_session WHERE id=? AND user_id=?"+(lock?" FOR UPDATE":""),mapper,id,user);if(rows.isEmpty())throw DomainException.missing();return rows.getFirst();}
 public Map<String,Object> view(GameState g){var data=new LinkedHashMap<String,Object>();data.put("id",g.id);data.put("kind",kind);data.put("definitionId",g.definitionId);data.put("state",g.state);data.put("progress",g.progress);data.put("selected",g.selected);data.put("readyAt",g.readyAt);data.put("resultId",g.resultId);data.put("version",g.version);return data;}
 @Transactional public Map<String,Object> start(UUID id,UUID user,String definition){var existing=db.query("SELECT * FROM game_session WHERE id=?",mapper,id);if(!existing.isEmpty()){if(!existing.getFirst().userId.equals(user))throw DomainException.missing();return view(existing.getFirst());}if(db.queryForObject("SELECT COUNT(*) FROM game_definition WHERE id=?",Integer.class,definition)==0)throw DomainException.invalid("Escolha uma atividade disponível.");var g=new GameState();g.id=id;g.userId=user;g.definitionId=definition;g.createdAt=System.currentTimeMillis();rules.start(g,g.createdAt);db.update("INSERT INTO game_session(id,user_id,definition_id,state,progress,selected,ready_at,result_id,version,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)",g.id,g.userId,g.definitionId,g.state,g.progress,String.join(",",g.selected),g.readyAt,g.resultId,g.version,g.createdAt);return view(g);}
 public Map<String,Object> get(UUID id,UUID user){return view(load(id,user,false));}
 @Transactional public Map<String,Object> action(UUID id,UUID user,UUID requestId,int expectedVersion,String action,String value){var g=load(id,user,true);var prior=db.queryForList("SELECT session_id FROM game_action WHERE id=?",requestId);if(!prior.isEmpty()){if(!id.equals(prior.getFirst().get("session_id")))throw DomainException.conflict("Essa ação já foi usada em outra partida.");return view(g);}if(g.version!=expectedVersion)throw DomainException.conflict("Essa partida mudou. Vamos recuperar a etapa atual.");rules.act(g,action,value,System.currentTimeMillis());g.version++;db.update("UPDATE game_session SET state=?,progress=?,selected=?,ready_at=?,result_id=?,version=? WHERE id=?",g.state,g.progress,String.join(",",g.selected),g.readyAt,g.resultId,g.version,g.id);db.update("INSERT INTO game_action(id,session_id,action_name,created_at) VALUES(?,?,?,?)",requestId,id,action,System.currentTimeMillis());return view(g);}
 public List<Map<String,Object>> history(UUID user){return db.query("SELECT * FROM game_session WHERE user_id=? AND state='FINISHED' ORDER BY created_at DESC LIMIT 30",mapper,user).stream().map(this::view).toList();}
}